            const d = k.slice(ATTENDANCE_DRAFT_PREFIX.length);
            const dr = readAttendanceDraft(d);
            const count = Object.keys(dr.rows).length;
            if (count > 0) out.push({
                date: d,
                count,
                pending: dr.pending
            });
